<div class="page-head"><div><p class="eyebrow">MariaDB Manager</p><h1>Database</h1></div><button class="btn btn-primary" data-modal-open="db-modal">+ Tạo database</button></div><?php if($flash):?><div class="alert <?=$flash['type']==='success'?'alert-success':'alert-error'?>"><?=nl2br(tms_h((string)$flash['message']))?></div><?php endif;?><?php if($error):?><div class="alert alert-error"><?=tms_h($error)?></div><?php endif;?><section class="table-card"><div class="simple-table head"><span>Tên database</span><span>Thao tác</span></div><?php foreach($databases as $db):?><div class="simple-table"><strong><?=tms_h($db)?></strong><div class="table-actions"><form method="post" action="/databases/export"><input type="hidden" name="csrf" value="<?=tms_h($csrf)?>"><input type="hidden" name="name" value="<?=tms_h($db)?>"><button class="btn btn-secondary">Xuất SQL</button></form><form method="post" action="/databases/import" enctype="multipart/form-data" class="import-form"><input type="hidden" name="csrf" value="<?=tms_h($csrf)?>"><input type="hidden" name="name" value="<?=tms_h($db)?>"><label class="btn btn-secondary"><input type="file" name="sql" accept=".sql" hidden required>Nhập SQL</label><button class="btn btn-secondary">Chạy</button></form><form method="post" action="/databases/drop" data-confirm="Xóa database <?=tms_h($db)?>?"><input type="hidden" name="csrf" value="<?=tms_h($csrf)?>"><input type="hidden" name="name" value="<?=tms_h($db)?>"><button class="btn btn-danger-soft">Xóa</button></form></div></div><?php endforeach;?><?php if(!$databases):?><div class="empty-state">Chưa có database người dùng.</div><?php endif;?></section><div class="modal" id="db-modal"><div class="modal-card"><button class="modal-close" data-modal-close>×</button><h2>Tạo database</h2><form method="post" action="/databases/create" class="stack"><input type="hidden" name="csrf" value="<?=tms_h($csrf)?>"><label><span>Tên database</span><input name="name" placeholder="project_db" required></labe